// Написан autotest-writer вручную (2 роли — генератор не умеет). spec: .qa/e2e/specs/chat-personal.md 1.2–1.4
// Пара new01 («QA П1 0010») ↔ new02 («QA П2 0011»), мэтч 63464537. Порядок важен: 1.2 смотрит окно блока, 1.3 пишет сообщение,
// 1.4 блокирует и снимает блок → serial. Всё @data: одноразовые refresh-токены сессий + общий мэтч.
// ВНИМАНИЕ: сервер не даёт удалить своё сообщение (DELETE → 200 []), каждое «QA-AUTO d6881a … Hi!» остаётся — в список чистки.
import { test, expect } from '../../fixtures';
import { captureApi, restDelete } from '../_shared/api';
import { saveSession } from '../_shared/session';
import { N1, N2, phone, openChat, expectBangAtEnd } from './chat-personal-helpers';

test.describe('Личный чат new01 ↔ new02', () => {
  test.describe.configure({ mode: 'serial', timeout: 180_000 });

  test('Чат открыт на последнем сообщении; блок из чата и из профиля: окно «לחסום את …?», «ביטול» — экран живой @iphone @data (#d6881a)', async ({ asUser }) => {
    const p = await asUser('new01');
    try {
      await phone(p);
      await openChat(p, N2);
      // Чат открывается на последнем сообщении (Р1): последний пузырь виден без прокрутки.
      await expect(p.getByTestId(/^bubble-(mine|peer)$/).last()).toBeInViewport();
      // Из чата: «⋯» → «חסימת …» → окно подтверждения (Р6, AC 10).
      await p.getByRole('button', { name: "פעולות על הצ'אט" }).click();
      const menu = p.getByRole('dialog');
      await expect(menu.getByText("פעולות על הצ'אט")).toBeVisible();
      await expect(menu.getByRole('button', { name: new RegExp(`דיווח על ${N2}`) })).toBeVisible();
      await menu.getByRole('button', { name: new RegExp(`חסימת ${N2}`) }).click();
      const confirm = p.getByRole('dialog');
      await expect(confirm.getByText(`לחסום את ${N2}?`)).toBeVisible();
      await expect(confirm.getByRole('button', { name: 'לחסום', exact: true })).toBeVisible();
      await confirm.getByRole('button', { name: 'ביטול', exact: true }).click();
      await expect(p.getByRole('dialog')).toHaveCount(0);
      // Экран не завис: меню открывается снова, поле ввода работает.
      await p.getByRole('button', { name: "פעולות על הצ'אט" }).click();
      await expect(p.getByRole('dialog').getByText("פעולות על הצ'אט")).toBeVisible();
      await p.getByRole('dialog').getByRole('button', { name: 'ביטול', exact: true }).click();
      await expect(p.getByRole('dialog')).toHaveCount(0);
      await p.getByRole('textbox', { name: 'כתוב הודעה' }).fill('QA-AUTO не отправлять');
      await expect(p.getByRole('button', { name: 'שליחה' })).toBeEnabled();
      await p.getByRole('textbox', { name: 'כתוב הודעה' }).fill('');

      // Из профиля: аватар в шапке → «פעולות על הפרופיל» → «חסימת …» → то же окно (Р6).
      await p.getByRole('button', { name: `לפרופיל של ${N2}` }).click();
      await p.waitForURL(/\/profile\//);
      await p.getByRole('button', { name: 'פעולות על הפרופיל' }).click();
      await p.getByRole('dialog').getByRole('button', { name: new RegExp(`חסימת ${N2}`) }).click();
      await expect(p.getByRole('dialog').getByText(`לחסום את ${N2}?`)).toBeVisible();
      await p.getByRole('dialog').getByRole('button', { name: 'ביטול', exact: true }).click();
      await expect(p.getByRole('dialog')).toHaveCount(0);
      await expect(p.getByRole('button', { name: 'פעולות על הפרופיל' })).toBeEnabled();
    } finally {
      await saveSession(p, 'new01');
    }
  });

  test('Латинское «… Hi!» от new01 — new02 видит без перезагрузки, ✓✓, «!» в конце у обоих и в списке @iphone @data (#d6881a)', async ({ asUser }) => {
    const a = await asUser('new01');
    const b = await asUser('new02');
    const phrase = `QA-AUTO d6881a ${Date.now()} Hi!`;
    let msgId: string | undefined;
    try {
      await phone(a);
      await phone(b);
      await openChat(b, N1); // получатель заранее в чате — проверяем realtime (AC 3)
      await openChat(a, N2);
      await a.getByRole('textbox', { name: 'כתוב הודעה' }).fill(phrase);
      const sent = a.waitForResponse((r) => r.url().includes('/rest/v1/messages') && r.request().method() === 'POST');
      await a.getByRole('button', { name: 'שליחה' }).click();
      const res = await sent;
      expect(res.status(), await res.text()).toBe(201);
      const body = await res.json().catch(() => null);
      const row = Array.isArray(body) ? body[0] : body;
      msgId = row?.id ? String(row.id) : undefined;

      // Отправитель: своё сообщение в ленте, поле очистилось, «!» в конце (AC 3, Р5).
      const mine = a.getByTestId('bubble-mine').filter({ hasText: phrase });
      await expect(mine).toHaveCount(1);
      await expect(a.getByRole('textbox', { name: 'כתוב הודעה' })).toHaveValue('');
      await expectBangAtEnd(mine, phrase);

      // Получатель: появилось без перезагрузки (AC 3), «!» в конце (Р5).
      const theirs = b.getByTestId('bubble-peer').filter({ hasText: phrase });
      await expect(theirs).toBeVisible({ timeout: 30_000 });
      await expectBangAtEnd(theirs, phrase);

      // Получатель прочитал (чат открыт) → у отправителя ✓✓ «прочитано» последним статусом (AC 4).
      await expect(a.getByTestId('tick-read').last()).toBeVisible({ timeout: 30_000 });

      // Превью в списке чатов получателя: строка new01 с этим текстом, «!» в конце (Р5).
      await b.goto('/matches');
      const preview = b.getByRole('button', { name: new RegExp(`^${N1} `) }).getByText(phrase, { exact: true });
      await expect(preview).toBeVisible();
      await expectBangAtEnd(preview, phrase);
    } finally {
      // Сервер не даёт удалять сообщения (DELETE → 200 []) — пробуем, иначе пометка для ручной чистки.
      const api = await captureApi(a, '/matches').catch(() => undefined);
      if (api && msgId) {
        const del = await restDelete(api, `messages?id=eq.${msgId}`);
        const gone = del.ok() && (await del.json().catch(() => [])).length > 0;
        if (!gone) test.info().annotations.push({ type: 'cleanup', description: `сообщение ${msgId} «${phrase}» (new01→new02) не удалено — в список чистки` });
      }
      await saveSession(a, 'new01');
      await saveSession(b, 'new02');
    }
  });

  test('Настоящий блок из чата: чат пропал у new01, экран не завис; снятие в «משתמשים חסומים» возвращает чат @iphone @data (#d6881a)', async ({ asUser }) => {
    const p = await asUser('new01');
    let blocked = false;
    try {
      await phone(p);
      await openChat(p, N2);
      await p.getByRole('button', { name: "פעולות על הצ'אט" }).click();
      await p.getByRole('dialog').getByRole('button', { name: new RegExp(`חסימת ${N2}`) }).click();
      await expect(p.getByRole('dialog').getByText(`לחסום את ${N2}?`)).toBeVisible();
      const w = p.waitForResponse((r) => /block/i.test(r.url()) && !['GET', 'HEAD', 'OPTIONS'].includes(r.request().method()));
      blocked = true;
      await p.getByRole('dialog').getByRole('button', { name: 'לחסום', exact: true }).click();
      expect((await w).ok(), 'запрос блокировки 2xx').toBeTruthy();
      // Экран не завис: окно закрылось, приложение отвечает — в списке чатов new02 нет (AC 10, Р6).
      await expect(p.getByRole('dialog')).toHaveCount(0);
      await p.goto('/matches');
      await expect(p.getByText('הודעות', { exact: true }).first()).toBeVisible();
      await expect(p.getByText(N2, { exact: true })).toHaveCount(0);

      // Снятие блока: /blocked-users → «ביטול חסימה» (+ подтверждение) → список пуст, чат вернулся.
      await unblock(p);
      blocked = false;
      await expect(async () => {
        await p.goto('/matches');
        await expect(p.getByText(N2, { exact: true }).last()).toBeVisible({ timeout: 10_000 });
      }).toPass({ timeout: 60_000 });
    } finally {
      let err: unknown;
      if (blocked) await unblock(p).catch((e) => (err = e));
      await saveSession(p, 'new01');
      if (err) throw new Error(`НЕ снят блок new01→new02: сними вручную (new01 → הגדרות → משתמשים חסומים → ביטול חסימה). ${err}`);
    }
  });
});

async function unblock(p: import('@playwright/test').Page) {
  await p.goto('/blocked-users');
  await expect(p.getByText('משתמשים חסומים').first()).toBeVisible();
  // Дождаться загрузки списка: либо строка партнёра, либо «אין משתמשים חסומים».
  const unblockBtn = p.getByRole('button', { name: `ביטול חסימה ${N2}` });
  await expect(unblockBtn.or(p.getByText('אין משתמשים חסומים'))).toBeVisible();
  if (!(await unblockBtn.count())) return;
  const w = p.waitForResponse((r) => /block/i.test(r.url()) && !['GET', 'HEAD', 'OPTIONS'].includes(r.request().method()));
  await unblockBtn.click();
  // Окно «לבטל את החסימה של …?» (r9) — подтверждаем; если окна нет, запрос уходит сразу.
  const dlg = p.getByRole('dialog');
  const first = await Promise.race([w.then(() => 'sent' as const), dlg.waitFor().then(() => 'dialog' as const)]);
  if (first === 'dialog') {
    await expect(dlg.getByText(`לבטל את החסימה של ${N2}?`)).toBeVisible();
    await dlg.getByRole('button', { name: 'לבטל חסימה', exact: true }).click();
  }
  expect((await w).ok(), 'запрос снятия блока 2xx').toBeTruthy();
  await expect(p.getByText('אין משתמשים חסומים')).toBeVisible();
}
